templates.cssStyles:
.slide-references .references-region {
    flex: 1;
    overflow-y: auto;
    padding: var(--spacing-md);
}
.references-list {
    list-style: none;
    padding-left: 0;
}
.references-list li {
    font-size: 14px;
    line-height: 1.6;
    margin-bottom: var(--spacing-sm);
    padding-left: var(--spacing-md);
    text-indent: calc(-1 * var(--spacing-md));
}
.references-list li em {
    font-style: italic;
}

.slide-thank-you {
    display: flex !important;
    justify-content: center;
    align-items: center;
    text-align: center;
}
.thank-you-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--spacing-lg);
}
.thank-you-message {
    font-size: 72px;
    font-weight: var(--font-weight-title);
    color: var(--color-primary);
    margin-bottom: var(--spacing-md);
}
.author-info {
    font-size: var(--font-size-body);
    color: var(--color-text-secondary);
}
.presenter-name {
    font-weight: 600;
    font-size: 28px;
    color: var(--color-text-primary);
}
.presenter-email {
    font-size: 20px;
    color: var(--color-primary);
}
.questions-prompt {
    font-size: 32px;
    color: var(--color-text-secondary);
    font-style: italic;
    margin-top: var(--spacing-lg);
}
.thank-you-logo {
    max-height: 80px;
    margin-bottom: var(--spacing-md);
}

themes.cssOverrides:
/* Academic: Left-aligned, formal, serif accents */
.slide-title {
    align-items: flex-start;
    text-align: left;
    padding-left: 100px;
}

.slide-title h1 {
    border-left: 5px solid var(--color-primary);
    padding-left: 28px;
}

.slide-title .subtitle {
    padding-left: 32px;
    font-style: italic;
}

.header-region h2 {
    border-bottom: 2px solid var(--color-border);
    padding-bottom: 16px;
}

.slide-content li::before {
    content: "■";
    font-size: 0.6em;
    top: 0.4em;
}

.slide-section {
    align-items: flex-start;
    text-align: left;
    padding-left: 100px;
}

.slide-quote blockquote {
    text-align: left;
    border-left: 4px solid var(--color-secondary);
    padding-left: 32px;
}

/* Dracula: Dramatic, uppercase titles, gothic feel */
.slide-title h1 {
    text-transform: uppercase;
    letter-spacing: 6px;
    border-bottom: 4px solid var(--color-secondary);
    padding-bottom: 24px;
}

.slide-title .subtitle {
    letter-spacing: 2px;
    opacity: 0.9;
}

.header-region h2 {
    text-transform: uppercase;
    letter-spacing: 3px;
}

.slide-content li::before {
    content: "›";
    font-size: 1.6em;
    font-weight: bold;
    color: var(--color-secondary);
    top: -0.1em;
}

.slide-section h1,
.slide-section h2 {
    text-transform: uppercase;
    letter-spacing: 8px;
    text-shadow: 0 0 40px var(--color-secondary);
}

.slide-quote blockquote {
    border-top: 2px solid var(--color-secondary);
    border-bottom: 2px solid var(--color-secondary);
    padding: 32px 0;
}

/* Modern: Centered, rounded, subtle shadows */
.slide-title h1 {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.slide-content li::before {
    content: "";
    width: 10px;
    height: 10px;
    background: var(--color-accent);
    border-radius: 50%;
    top: 0.5em;
}

.slide-section {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
}

.header-region h2 {
    padding-bottom: 12px;
    border-bottom: 3px solid var(--color-accent);
    display: inline-block;
}

/* Night: Floating cards, soft glows, modern dark UI */
.slide {
    background: linear-gradient(180deg, var(--color-background) 0%, #1e2030 100%);
}

.slide-title h1 {
    text-shadow: 0 0 60px var(--color-primary);
}

.header-region h2 {
    background: var(--color-surface);
    padding: 16px 28px;
    border-radius: 8px;
    display: inline-block;
    box-shadow: 0 4px 20px rgba(0,0,0,0.3);
}

.slide-content li {
    background: var(--color-surface);
    padding: 16px 24px;
    border-radius: 8px;
    margin-bottom: 16px;
    box-shadow: 0 2px 12px rgba(0,0,0,0.2);
}

.slide-content li::before {
    content: "○";
    color: var(--color-accent);
    position: static;
    margin-right: 16px;
}

.slide-section {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
    box-shadow: inset 0 0 100px rgba(0,0,0,0.3);
}

.slide-quote {
    background: var(--color-surface);
    border-radius: 24px;
    margin: 40px;
    box-shadow: 0 8px 40px rgba(0,0,0,0.4);
}

/* Sidebar Layout Override */
.slide {
    padding-left: 120px !important; /* Make room for sidebar */
}
.slide::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    bottom: 0;
    width: 100px;
    background: var(--color-primary);
    z-index: 0;
}
.slide::after {
    content: '';
    position: absolute;
    top: 0;
    left: 100px;
    bottom: 0;
    width: 10px;
    background: rgba(0,0,0,0.05);
    z-index: 0;
}
.slide-title {
    padding-left: var(--spacing-lg) !important; /* Reset padding for title */
    background: var(--color-primary);
    color: white !important;
}
.slide-title .main-title {
    color: white !important;
}
.slide-title .subtitle, .slide-title .author, .slide-title .date {
    color: rgba(255,255,255,0.9) !important;
}
.slide-title::before, .slide-title::after {
    display: none; /* Remove sidebar from title slide */
}

/* Decoration */
.slide-content .header-region {
    border-bottom: 2px solid var(--color-surface);
    padding-bottom: var(--spacing-sm);
}

.academic-info {
    margin-top: var(--spacing-md);
    padding-top: var(--spacing-md);
    border-top: 1px solid rgba(255,255,255,0.2);
}

/* Simple: Maximum whitespace, no decorations, classic typography */
.slide-title {
    align-items: flex-start;
    text-align: left;
}

.slide-title h1 {
    font-weight: 400;
    line-height: 1.2;
}

.slide-title .subtitle {
    font-style: italic;
    margin-top: 16px;
}

.header-region h2 {
    font-weight: 400;
}

.slide-content li::before {
    content: "—";
    font-weight: normal;
}

.slide-content li {
    padding-left: 48px;
}

.slide-section {
    background: var(--color-background);
    color: var(--color-text-primary);
    border-top: 1px solid var(--color-border);
    border-bottom: 1px solid var(--color-border);
}

.slide-quote blockquote {
    font-size: calc(var(--font-size-heading) * 1.3);
    font-weight: 400;
}

.slide-quote .author {
    font-style: italic;
}

/* Solarized: Classic, warm, elegant serif */
.slide-title h1 {
    font-weight: 400;
    font-style: italic;
}

.slide-title .subtitle {
    letter-spacing: 1px;
}

.header-region h2 {
    font-weight: 400;
    border-bottom: 1px solid var(--color-border);
    padding-bottom: 12px;
}

.slide-content li::before {
    content: "—";
    font-weight: normal;
    color: var(--color-accent);
}

.slide-section {
    background: var(--color-surface);
    color: var(--color-primary);
}

.slide-section h1,
.slide-section h2 {
    font-weight: 400;
    font-style: italic;
}

.slide-quote blockquote {
    font-weight: 400;
    font-size: calc(var(--font-size-heading) * 1.2);
}

/* UMaT Specific Styles */
.slide-title .main-title {
    color: var(--color-primary);
    text-transform: uppercase;
    border-bottom: 2px solid var(--color-secondary);
    padding-bottom: 1rem;
    margin-bottom: 1rem;
}
.slide-title {
    background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
    border: 10px solid var(--color-primary);
}
.university-badge {
    filter: drop-shadow(0 2px 4px rgba(0,0,0,0.2));
}
.slide-number {
    font-weight: bold;
    color: var(--color-primary);
}
/* Figure titles below, Table titles above */
.slide-image .image-caption {
    margin-top: 10px;
    order: 2; /* Ensure it is visually below if flex used */
    font-style: italic;
}

/* Academic Info */
.degree-statement {
    font-style: italic;
    margin-top: 24px;
    font-size: var(--font-size-body);
    color: var(--color-text-secondary);
}
.supervisor-info {
    margin-top: 12px;
    font-weight: bold;
    color: var(--color-text-primary);
}
